{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-8021qO/src/address.js","content":"/**
 * Cell address helpers: column letters run A..Z then AA..ZZ (1..702), rows
 * are 1..999 (one to three digits). Letters are read case-insensitively and
 * normalized to upper case.
 */

const MAX_COL = 702 // ZZ
const MAX_ROW = 999 // three digits

export function colLettersToNumber(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

export function colNumberToLetters(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  const first = Math.floor((n - 1) / 26)
  const second = ((n - 1) % 26) + 1
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}

/**
 * Classifies a word (letters followed by optional digits) as a cell
 * address. Returns null when it is not one or two letters and one to three
 * digits naming a row of at least 1 - that is, when it is syntactically a
 * word but outside the addressable range.
 */
export function classifyAddress(word) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(word)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const digits = m[2]
  if (letters.length < 1 || letters.length > 2) return null
  if (digits.length < 1 || digits.length > 3) return null
  const row = parseInt(digits, 10)
  if (row < 1) return null
  const col = colLettersToNumber(letters)
  if (col > MAX_COL || row > MAX_ROW) return null
  return { col, row, letters, key: letters + String(row) }
}

export function keyFromColRow(col, row) {
  return colNumberToLetters(col) + String(row)
}

export function compareAddressKeys(a, b) {
  const pa = parseKey(a)
  const pb = parseKey(b)
  if (pa.col !== pb.col) return pa.col - pb.col
  return pa.row - pb.row
}

function parseKey(key) {
  const m = /^([A-Za-z]+)([0-9]+)$/.exec(key)
  return { col: colLettersToNumber(m[1]), row: parseInt(m[2], 10) }
}
"}

