 * Tokenizer for formula bodies (the text after the leading `=`).
 */

const TOKEN_RE =
  /^(?:(?<ws>[ \t]+)|(?<num>\d+(?:\.\d+)?)|(?<word>[A-Za-z]+[0-9]*)|(?<op><=|>=|<>|[<>=+\-*/^])|(?<lparen>\()|(?<rparen>\))|(?<comma>,)|(?<colon>:))/

export class LexError extends Error {}

export function tokenize(src) {
  const tokens = []
  let pos = 0
  while (pos < src.length) {
    const m = TOKEN_RE.exec(src.slice(pos))
    if (!m) throw new LexError(`unexpected character at ${pos}`)
    const g = m.groups
    if (g.ws !== undefined) {
      // skip whitespace
    } else if (g.num !== undefined) {
      tokens.push({ type: 'num', value: g.num })
    } else if (g.word !== undefined) {
      tokens.push({ type: 'word', value: g.word })
    } else if (g.op !== undefined) {
      tokens.push({ type: 'op', value: g.op })
    } else if (g.lparen !== undefined) {
      tokens.push({ type: 'lparen', value: '(' })
    } else if (g.rparen !== undefined) {
      tokens.push({ type: 'rparen', value: ')' })
    } else if (g.comma !== undefined) {
      tokens.push({ type: 'comma', value: ',' })
    } else if (g.colon !== undefined) {
      tokens.push({ type: 'colon', value: ':' })
    }
    pos += m[0].length
  }
  return tokens
}
"}

