{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-8021qO/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies. Precedence, loosest first:
 * comparisons, then + -, then * /, then ^ (right associative), then a
 * leading unary sign (binds tighter than ^). Ranges (`A1:B3`) are only
 * accepted directly as a function call argument.
 */

import { tokenize } from './lexer.js'
import { classifyAddress } from './address.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const ADD_OPS = new Set(['+', '-'])
const MUL_OPS = new Set(['*', '/'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type, value) {
    const t = this.peek()
    if (!t || t.type !== type || (value !== undefined && t.value !== value)) {
      throw new ParseError('unexpected token')
    }
    return this.next()
  }

  parseProgram() {
    const node = this.parseComparison()
    if (this.pos !== this.tokens.length) throw new ParseError('trailing input')
    return node
  }

  parseComparison() {
    let node = this.parseAdd()
    while (this.peek() && this.peek().type === 'op' && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdd()
      node = { type: 'binop', op, left: node, right }
    }
    return node
  }

  parseAdd() {
    let node = this.parseMul()
    while (this.peek() && this.peek().type === 'op' && ADD_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseMul()
      node = { type: 'binop', op, left: node, right }
    }
    return node
  }

  parseMul() {
    let node = this.parsePow()
    while (this.peek() && this.peek().type === 'op' && MUL_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parsePow()
      node = { type: 'binop', op, left: node, right }
    }
    return node
  }

  parsePow() {
    const base = this.parseUnary()
    if (this.peek() && this.peek().type === 'op' && this.peek().value === '^') {
      this.next()
      const right = this.parsePow()
      return { type: 'binop', op: '^', left: base, right }
    }
    return base
  }

  parseUnary() {
    if (this.peek() && this.peek().type === 'op' && ADD_OPS.has(this.peek().value)) {
      const op = this.next().value
      const expr = this.parseUnary()
      return { type: 'unary', op, expr }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new ParseError('unexpected end of input')
    if (t.type === 'num') {
      this.next()
      return { type: 'num', value: parseFloat(t.value) }
    }
    if (t.type === 'lparen') {
      this.next()
      const node = this.parseComparison()
      this.expect('rparen')
      return node
    }
    if (t.type === 'word') {
      this.next()
      const upper = t.value.toUpperCase()
      if (this.peek() && this.peek().type === 'lparen') {
        return this.parseCall(t.value)
      }
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return makeAddrNode(t.value)
    }
    throw new ParseError('unexpected token')
  }

  parseCall(name) {
    this.expect('lparen')
    const args = []
    if (!(this.peek() && this.peek().type === 'rparen')) {
      args.push(this.parseArg())
      while (this.peek() && this.peek().type === 'comma') {
        this.next()
        args.push(this.parseArg())
      }
    }
    this.expect('rparen')
    return { type: 'call', name, args }
  }

  parseArg() {
    const t = this.peek()
    const t2 = this.tokens[this.pos + 1]
    const t3 = this.tokens[this.pos + 2]
    if (t && t.type === 'word' && t2 && t2.type === 'colon' && t3 && t3.type === 'word') {
      this.next()
      this.next()
      this.next()
      return { type: 'range', from: makeAddrNode(t.value), to: makeAddrNode(t3.value) }
    }
    return this.parseComparison()
  }
}

