 * Value construction, conversion and formatting for the sheet's four value
 * kinds: number, text, boolean and error.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function numVal(v) {
  return { t: 'num', v }
}
export function textVal(v) {
  return { t: 'text', v }
}
export function boolVal(v) {
  return { t: 'bool', v }
}
export function errVal(v) {
  return { t: 'err', v }
}

/** Converts a value to a number for an arithmetic position. */
export function toNumber(value) {
  if (value.t === 'num') return value
  if (value.t === 'bool') return numVal(value.v ? 1 : 0)
  if (value.t === 'text') return errVal('#VALUE!')
  return value // error passes through unchanged
}

/** Wraps an arithmetic result, turning non-finite results into #DIV/0!. */
export function finiteNum(n) {
  if (!Number.isFinite(n)) return errVal('#DIV/0!')
  return numVal(n)
}

function rank(v) {
  return v.t === 'num' ? 0 : v.t === 'text' ? 1 : 2
}

/** Compares two non-error values, returning -1, 0 or 1. */
export function compareValues(l, r) {
  const rl = rank(l)
  const rr = rank(r)
  if (rl !== rr) return rl < rr ? -1 : 1
  if (l.t === 'num') return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  if (l.t === 'text') return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  const lv = l.v ? 1 : 0
  const rv = r.v ? 1 : 0
  return lv < rv ? -1 : lv > rv ? 1 : 0
}

/** Formats a number the way JavaScript prints it after rounding to ten
 * significant digits. */
export function formatNumber(n) {
  return String(parseFloat(n.toPrecision(10)))
}

export function formatValue(value) {
  if (value.t === 'num') return formatNumber(value.v)
  if (value.t === 'text') return value.v
  if (value.t === 'bool') return value.v ? 'TRUE' : 'FALSE'
  return value.v
}
"}

