    this.cells = cells
    this.cache = new Map()
    this.pending = new Set()
  }

  /** Evaluates the cell at the given canonical address, memoized. */
  evalAddress(key) {
    if (this.cache.has(key)) return this.cache.get(key)
    if (this.pending.has(key)) return errVal('#CYCLE!')
    this.pending.add(key)
    const content = this.cells.has(key) ? this.cells.get(key) : ''
    const value = this.evalContent(content)
    this.pending.delete(key)
    this.cache.set(key, value)
    return value
