      case 'num':
        return numVal(node.value)
      case 'bool':
        return boolVal(node.value)
      case 'addr':
        if (!node.valid) return errVal('#REF!')
        return this.evalAddress(node.key)
      case 'unary':
        return this.evalUnary(node)
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unreachable node type ${node.type}`)
    }
  }

  evalUnary(node) {
    const v = this.evaluate(node.expr)
    const n = toNumber(v)
    if (n.t === 'err') return n
    return numVal(node.op === '-' ? -n.v : n.v)
