      if (right.t === 'err') return right
      const cmp = compareValues(left, right)
      return boolVal(applyComparison(node.op, cmp))
    }
    const ln = toNumber(left)
    if (ln.t === 'err') return ln
    const rn = toNumber(right)
    if (rn.t === 'err') return rn
