import { parseFormula } from './parser.js'
import { keyFromColRow, compareAddressKeys } from './address.js'

/** Returns the sorted list of distinct cell addresses the content names
 * directly. A literal, or a formula the grammar rejects, names none. */
export function directDeps(content) {
  if (!content.startsWith('=')) return []
  const ast = parseFormula(content.slice(1))
  if (!ast) return []
  const out = new Set()
  collect(ast, out)
  return [...out].sort(compareAddressKeys)
}

function collect(node, out) {
  switch (node.type) {
    case 'num':
    case 'bool':
      break
    case 'addr':
      if (node.valid) out.add(node.key)
      break
    case 'range':
      if (node.from.valid && node.to.valid) {
        const minCol = Math.min(node.from.col, node.to.col)
        const maxCol = Math.max(node.from.col, node.to.col)
        const minRow = Math.min(node.from.row, node.to.row)
        const maxRow = Math.max(node.from.row, node.to.row)
        for (let c = minCol; c <= maxCol; c++) {
          for (let r = minRow; r <= maxRow; r++) {
            out.add(keyFromColRow(c, r))
          }
        }
      }
      break
    case 'unary':
      collect(node.expr, out)
      break
    case 'binop':
      collect(node.left, out)
      collect(node.right, out)
      break
    case 'call':
      for (const arg of node.args) collect(arg, out)
      break
    default:
      throw new Error(`unreachable node type ${node.type}`)
  }
