{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-8021qO/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { SheetEvaluator } from './evaluator.js'
import { directDeps } from './deps.js'
import { formatValue } from './values.js'
import { compareAddressKeys } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  return require('node:fs').readFileSync(0, 'utf8')
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
  }

  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  const input = chunks.join('')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const addresses = [...cells.keys()].sort(compareAddressKeys)
  const lines = []

  if (mode === 'values') {
    const evaluator = new SheetEvaluator(cells)
    for (const addr of addresses) {
      const value = evaluator.evalAddress(addr)
      lines.push(`${addr}=${formatValue(value)}`)
    }
  } else {
    for (const addr of addresses) {
      const deps = directDeps(cells.get(addr))
      lines.push(`${addr}: ${deps.join(' ')}`.replace(/: $/, ':'))
    }
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
}

main()
"}

